var numSteps = function(s) {
    const arr = s.split('');
    let res = 0;

    while (arr.length > 1) {
        res++;

        if (arr[arr.length - 1] === '0') {
            arr.pop();
            continue;
        }

        let carry = 1;

        for (let i = arr.length - 1; i >= 0; i--) {
            if (arr[i] === '0') {
                arr[i] = '1';
                carry = 0;
                break;
            }

            arr[i] = '0';
        }

        if (carry) {
            arr.unshift('1');
        }
    }

    return res;
};
